def valid_position(s):
    # must be exactly digits,digits with optional leading + and leading zeros, no spaces, no empty, no negative, no extra commas
    if s == "":
        return False
    if "," not in s:
        return False
    parts = s.split(",")
    if len(parts) != 2:
        return False
    for p in parts:
        if p == "":
            return False
        # allow leading +? Observed +1,+4 works. Allow single leading +.
        if p.startswith("+"):
            p2 = p[1:]
            if p2 == "" or not p2.isdigit():
                return False
            # check p2 is digits (allow leading zeros)
            continue
        if p.startswith("-"):
            return False
        if not p.isdigit():
            return False
        # also need to handle "01"? That's digits, ok. "1.0"? contains ., not digits, false. Good.
        # "0x1"? contains x, false. Good.
    return True

